    expect(parity.assets).toEqual([]);
  });

  it.each(fullAddFiles)('pins and exactly reverses the complete new source %s', file => {
    const row = parity.sources.find(item => item.file === file)!;
    expect(row.before_sha256).toBe(sha(''));
