  it.each(fullAddFiles)('rejects current or recorded full-add drift at %s', file => {
    const row = parity.sources.find(item => item.file === file)!;
    expect(() => reverseRouteSourceFollowup(read(file) + '\n// unreviewed\n', row)).toThrow();
